        return 0

    def pos_from(obj):
        if not isinstance(obj, dict):
            return None
        for px, py in (("x", "y"), ("pos_x", "pos_y"), ("row", "col")):
            if px in obj and py in obj:
                try:
                    return (int(obj.get(px, 0)), int(obj.get(py, 0)))
                except Exception:
                    return None
        p = obj.get("pos")
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            try:
