            for key in ("self", "agent", "me"):
                p = pos_from(grid.get(key))
                if p is not None:
                    return p
        return (0, 0)

    def iter_positions(value):
        if value is None:
            return
        if isinstance(value, dict):
            p = pos_from(value)
            if p is not None:
                yield p, value
            else:
                for v in value.values():
                    for item in iter_positions(v):
                        yield item
        elif isinstance(value, (list, tuple)):
            for v in value:
                for item in iter_positions(v):
